#include <bits/stdc++.h>
using namespace std;

struct RootedTree {
    vector<int> par, depth, subtree;
};

RootedTree analyze_tree(const vector<vector<int>>& adj) {
    int n = static_cast<int>(adj.size()) - 1;
    RootedTree result{vector<int>(n + 1),
                      vector<int>(n + 1),
                      vector<int>(n + 1, 1)};
    vector<int> order, pending{1};
    order.reserve(n);

while (!pending.empty()) {
    int vertex = pending.back();
    pending.pop_back();
    order.push_back(vertex);
    for (int neighbor : adj[vertex]) {
        if (neighbor == result.par[vertex]) {
            continue;
        }
        result.par[neighbor] = vertex;
        result.depth[neighbor] = result.depth[vertex] + 1;
        pending.push_back(neighbor);
    }
}

    for (int i = n - 1; i > 0; --i) {
        int vertex = order[i];
        result.subtree[result.par[vertex]] += result.subtree[vertex];
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> adj(n + 1);
    for (int edge = 0; edge < n - 1; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }
    RootedTree result = analyze_tree(adj);
    for (const vector<int>* a : {&result.par, &result.depth, &result.subtree}) {
        for (int vertex = 1; vertex <= n; ++vertex) {
            cout << (*a)[vertex] << (vertex == n ? '\n' : ' ');
        }
    }
}

